{
  "packet_id": "H6-T01-3",
  "claim_id": "C024",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C024.component",
    "value": "Changes should not be combined when their effects could not be distinguished.",
    "scope": "A conditional restriction on trial composition, not a blanket assertion that all combined changes are uninterpretable.",
    "provenance": {
      "refs": [
        {
          "source_id": "P015",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly supplies the restriction and its condition within a narrowly scoped, reversible trial."
    }
  },
  "signal_basis": {
    "component_id": "C024.signal_basis",
    "value": "Compare candidate changes against corroborated failure patterns and prospectively monitor the selected trial's outcomes against comparable baseline bookings. Improvement supports further testing without alone establishing causation.",
    "scope": "Evaluating a selected trial through failure patterns, operational outcomes and baseline comparisons accounting for equipment, crew and demand differences.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply candidate comparison, prospective outcome monitoring and the qualified interpretation of baseline-relative improvement."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C024.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The restriction is supported without an unresolved empirical relation."
    }
  },
  "rationale": "When combined changes have indistinguishable effects, observed outcomes cannot distinguish their individual contributions. Avoiding such combinations is therefore warranted for the mapping's narrowly scoped trial and evaluation. This does not assert that every combined intervention is uninterpretable or that testing one change establishes causation.",
  "uncertainty": "Which particular combinations would have indistinguishable effects is unspecified; the claim applies only when that condition holds.",
  "anomalies": []
}
